    public function __construct(?BaseConnection $db = null) { $this->db=$db?:db_connect(); $this->leads=new CrmLeadModel($this->db); $this->followUps=new CrmLeadFollowUpModel($this->db); $this->history=new CrmLeadHistoryModel($this->db); $this->statuses=new CrmLeadStatusModel($this->db); $this->sources=new CrmLeadSourceModel($this->db); $this->telephoneCodes=new TelephoneCountryCode($this->db); $this->services=new ServiceModel($this->db); }
    public static function genderOptions(): array { return ['Male' => 'Male', 'Female' => 'Female', 'Other' => 'Other']; }
    public function clinicId(): int { return (int)((session('user')??[])['clinic_id']??0); }
    public function masters(): array { $types=$this->db->table('follow_up_types')->where('status',1)->orderBy('sort_order')->orderBy('name')->get()->getResultArray(); $followStatuses=$this->db->table('follow_up_statuses')->where('status',1)->orderBy('sort_order')->orderBy('name')->get()->getResultArray(); $priorities=$this->db->table('crm_lead_priorities')->where('status',1)->orderBy('sort_order')->orderBy('name')->get()->getResultArray(); $leadQuery=$this->db->table('crm_leads')->select('id,lead_number,full_name')->where('deleted_at',null); if($this->clinicId()>0)$leadQuery->groupStart()->where('clinic_id',$this->clinicId())->orWhere('clinic_id',null)->groupEnd(); $services=$this->services->forScope($this->clinicId()>0?$this->clinicId():null)->where('status',1)->orderBy('name')->findAll(); $assignedUsers=$this->db->table('users')->select('id,username')->where('status',1)->where('deleted_at',null)->orderBy('username')->get()->getResultArray(); return ['statuses'=>$this->statuses->where('status',1)->orderBy('sort_order')->findAll(),'sources'=>$this->sources->where('status',1)->orderBy('sort_order')->findAll(),'priorities'=>$priorities,'services'=>$services,'followUpTypes'=>$types,'followUpStatuses'=>$followStatuses,'assignedUsers'=>$assignedUsers,'leadOptions'=>$leadQuery->orderBy('id','DESC')->limit(200)->get()->getResultArray(),'telephoneCodes'=>$this->telephoneCodes->dropdown()]; }
    public function listLeads(array $filters,int $page=1,int $perPage=20): array { $q=$this->db->table('crm_leads l')->select('l.*,s.name AS status_name,s.code AS status_code,src.name AS source_name,COALESCE(l.country_code,tc.normalized_code) AS lead_country_code')->join('crm_lead_statuses s','s.id=l.lead_status_id')->join('crm_lead_sources src','src.id=l.source_id','left')->join('telephone_country_codes tc','tc.id=l.telephone_country_code_id','left'); if($this->clinicId()>0)$q->groupStart()->where('l.clinic_id',$this->clinicId())->orWhere('l.clinic_id',null)->groupEnd(); if(($filters['search']??'')!=='')$q->groupStart()->like('l.lead_number',$filters['search'])->orLike('l.full_name',$filters['search'])->orLike('l.mobile_number',$filters['search'])->orLike('l.mobile_normalized',$filters['search'])->orLike('l.email',$filters['search'])->groupEnd(); foreach(['status_id'=>'l.lead_status_id','source_id'=>'l.source_id','priority'=>'l.priority','assigned_user_id'=>'l.assigned_user_id'] as $key=>$field)if(($filters[$key]??'')!=='')$q->where($field,$filters[$key]); if(($filters['from']??'')!=='')$q->where('l.created_at >=',$filters['from'].' 00:00:00'); if(($filters['to']??'')!=='')$q->where('l.created_at <=',$filters['to'].' 23:59:59'); $total=(clone $q)->countAllResults(); $page=max(1,$page); $offset=($page-1)*$perPage; $pager=service('pager'); $pager->makeLinks($page, $perPage, $total,'default_full',0,'crm_leads'); $rows=$q->orderBy('l.id','DESC')->limit($perPage, $offset)->get()->getResultArray(); return ['rows'=>$this->decorateRows($rows),'pager'=>$pager,'total'=>$total]; }
    public function listFollowUps(array $filters,int $page=1,int $perPage=20): array { $q=$this->db->table('crm_lead_followups f')->select('f.*,l.lead_number,l.full_name,l.mobile_number,l.country_code,l.telephone_country_code_id,COALESCE(l.country_code,tc.normalized_code) AS lead_country_code,ft.name AS follow_up_type_name,au.username AS assigned_user_name')->join('crm_leads l','l.id=f.lead_id')->join('telephone_country_codes tc','tc.id=l.telephone_country_code_id','left')->join('follow_up_types ft','ft.id=f.follow_up_type_id','left')->join('users au','au.id=f.assigned_user_id','left'); if($this->clinicId()>0)$q->where('f.clinic_id',$this->clinicId()); if(($filters['search']??'')!=='')$q->groupStart()->like('f.follow_up_number',$filters['search'])->orLike('l.lead_number',$filters['search'])->orLike('l.full_name',$filters['search'])->orLike('l.mobile_number',$filters['search'])->orLike('l.mobile_normalized',$filters['search'])->groupEnd(); foreach(['follow_up_status'=>'f.follow_up_status','assigned_user_id'=>'f.assigned_user_id','follow_up_type_id'=>'f.follow_up_type_id','lead_id'=>'f.lead_id'] as $key=>$field)if(($filters[$key]??'')!=='')$q->where($field,$filters[$key]); if(($filters['from']??'')!=='')$q->where('f.follow_up_date >=',$filters['from']); if(($filters['to']??'')!=='')$q->where('f.follow_up_date <=',$filters['to']); $total=(clone $q)->countAllResults(); $page=max(1,$page); $offset=($page-1)*$perPage; $pager=service('pager'); $pager->makeLinks($page, $perPage, $total,'default_full',0,'crm_followups'); $rows=$q->orderBy('f.follow_up_date','DESC')->orderBy('f.follow_up_time','DESC')->limit($perPage, $offset)->get()->getResultArray(); return ['rows'=>$this->decorateRows($rows),'pager'=>$pager,'total'=>$total]; }
    public function findLead(int $id): ?array { $q=$this->db->table('crm_leads l')->select('l.*,s.name AS status_name,s.code AS status_code,src.name AS source_name,COALESCE(l.country_code,tc.normalized_code) AS lead_country_code')->join('crm_lead_statuses s','s.id=l.lead_status_id')->join('crm_lead_sources src','src.id=l.source_id','left')->join('telephone_country_codes tc','tc.id=l.telephone_country_code_id','left')->where('l.id',$id); if($this->clinicId()>0)$q->groupStart()->where('l.clinic_id',$this->clinicId())->orWhere('l.clinic_id',null)->groupEnd(); $lead=$q->get()->getRowArray(); return $lead?$this->decorateRows([$lead])[0]:null; }
    public function findFollowUp(int $id): ?array { $q=$this->followUps->where('id',$id); if($this->clinicId()>0)$q->where('clinic_id',$this->clinicId()); return $q->first(); }
    public function saveLead(array $input,?int $id,int $actor): array { $errors=[]; $name=trim((string)($input['full_name']??'')); $mobile=trim((string)($input['mobile_number']??'')); $manual=(string)($input['country_code_manual']??'')==='1'; $codeId=(int)($input['telephone_country_code_id']??0); $statusId=(int)($input['lead_status_id']??0); $code=$manual?null:($codeId>0?$this->telephoneCodes->where('id',$codeId)->where('status',1)->first():null); $countryCode=$manual?TelephoneCountryCode::normalizeCode((string)($input['country_code']??'')):($code['normalized_code']??null); $normalized=(new TelephoneContactService())->normalizedMobile($mobile); $priority=(string)($input['priority']??'normal'); $gender=trim((string)($input['gender']??'')); if($name==='')$errors['full_name']='Full name is required.'; if($gender!==''&&!array_key_exists($gender,self::genderOptions()))$errors['gender']='Select a valid gender.'; if($gender!==''&&strlen($gender)>20)$errors['gender']='Gender must not exceed 20 characters.'; if($countryCode===null)$errors[$manual?'country_code':'telephone_country_code_id']=$manual?'Enter a valid telephone country code.':'Select an active telephone country code.'; if($manual&&trim((string)($input['telephone_country_name']??''))==='')$errors['telephone_country_name']='Country name is required when entering a code manually.'; if($mobile==='')$errors['mobile_number']='Mobile number is required.'; elseif(!preg_match('/^[0-9][0-9 ()-]{6,19}$/',$mobile)||$normalized===null||!preg_match('/^[0-9]{7,20}$/',$normalized))$errors['mobile_number']='Enter a valid mobile number.'; if(($input['email']??'')!==''&&!filter_var(trim((string)$input['email']),FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email address.'; if(!$this->statuses->where(['id'=>$statusId,'status'=>1])->first())$errors['lead_status_id']='Select an active lead status.'; if(!$this->db->table('crm_lead_priorities')->where(['code'=>$priority,'status'=>1])->get()->getRowArray())$errors['priority']='Se