his->leads->update($id,$data);$this->record($id,'updated',$lead,$data,$actor);return $this->findLead($id)??$data;} $data['created_by']=$actor; $data['lead_number']='TEMP-'.bin2hex(random_bytes(5)); $newId=$this->leads->insert($data,true); $this->leads->update($newId,['lead_number'=>'LEAD-'.str_pad((string)$newId,6,'0',STR_PAD_LEFT)]); $this->record($newId,'created',null,$data,$actor); return $this->findLead((int)$newId)??[]; }
    public function saveFollowUp(array $input,?int $id,int $actor): array { $leadId=(int)($input['lead_id']??0); $lead=$this->findLead($leadId); if(!$lead)throw new RuntimeException(json_encode(['lead_id'=>'Select a valid lead in your permitted clinic scope.'])); $date=$this->date($input['follow_up_date']??''); $time=trim((string)($input['follow_up_time']??'')); $typeId=(int)($input['follow_up_type_id']??0); $status=trim((string)($input['follow_up_status']??'')); $assignedUserId=(int)($input['assigned_user_id']??0); $errors=[]; if(!$date)$errors['follow_up_date']='Enter a valid follow-up date.'; if(!preg_match('/^\d{2}:\d{2}(:\d{2})?$/',$time))$errors['follow_up_time']='Enter a valid follow-up time.'; $type=$this->db->table('follow_up_types')->where(['id'=>$typeId,'status'=>1])->get()->getRowArray(); if(!$type)$errors['follow_up_type_id']='Select an active follow-up type.'; $statusRow=$this->db->table('follow_up_statuses')->where(['code'=>$status,'status'=>1])->get()->getRowArray(); if(!$statusRow)$errors['follow_up_status']='Select an active follow-up status.'; if($assignedUserId>0){$assignedUser=$this->db->table('users')->select('id')->where(['id'=>$assignedUserId,'status'=>1,'deleted_at'=>null])->get()->getRowArray();if(!$assignedUser)$errors['assigned_user_id']='Select an active assigned user.';} if($errors)throw new RuntimeException(json_encode($errors)); $followupClinicId=(int)($lead['clinic_id']??0);if($followupClinicId<1)$followupClinicId=(int)$this->db->table('clinics')->select('id')->where('status',1)->orderBy('id','ASC')->get()->getRow('id');if($followupClinicId<1)throw new RuntimeException('No active clinic is configured for follow-ups.');$data=['lead_id'=>$lead['id'],'clinic_id'=>$followupClinicId,'patient_id'=>$lead['converted_patient_id']?:null,'follow_up_date'=>$date,'follow_up_time'=>strlen($time)===5?$time.':00':$time,'follow_up_type_id'=>$typeId,'follow_up_status'=>$status,'assigned_user_id'=>$assignedUserId?:null,'remarks'=>trim((string)($input['remarks']??''))?:null,'updated_by'=>$actor]; $this->db->transBegin(); try { if($id){$old=$this->findFollowUp($id);if(!$old||$old['lead_id']!=$lead['id'])throw new RuntimeException('Follow-up not found.');$this->followUps->update($id,$data);$this->record($lead['id'],'follow_up_updated',$old,$data,$actor,$id);$newId=$id;}else{$data['created_by']=$actor;$data['follow_up_number']='TEMP-'.bin2hex(random_bytes(5));$newId=$this->followUps->insert($data,true);$this->followUps->update($newId,['follow_up_number'=>'FUP-'.str_pad((string)$newId,6,'0',STR_PAD_LEFT)]);$this->record($lead['id'],'follow_up_created',null,$data,$actor,(int)$newId);} if(!$this->db->transStatus())throw new RuntimeException('Follow-up could not be saved.');$this->db->transCommit();return $this->findFollowUp((int)$newId)??$data; }catch(\Throwable $e){$this->db->transRollback();throw $e;} }
    public function transitionFollowUp(int $id,string $status,int $actor): array { $f=$this->findFollowUp($id);if(!$f)throw new RuntimeException('Follow-up not found.');$allowed=['scheduled'=>['completed','rescheduled','cancelled','missed'],'rescheduled'=>['completed','rescheduled','cancelled','missed'],'completed'=>[],'cancelled'=>[],'missed'=>[]];if(!in_array($status,$allowed[$f['follow_up_status']]??[],true))throw new RuntimeException('Invalid follow-up status transition.');$data=['follow_up_status'=>$status,'updated_by'=>$actor];if($status==='completed'){$data['completed_at']=date('Y-m-d H:i:s');$data['completed_by']=$actor;}$this->followUps->update($id,$data);$this->record((int)$f['lead_id'],'follow_up_'.$status,$f,$data,$actor,$id);return $this->findFollowUp($id)??[]; }
    public function history(int $id): array { $lead=$this->findLead($id);if(!$lead)throw new RuntimeException('Lead not found.');$rows=$this->historyRows($id,(int)$lead['clinic_id'])->findAll();return $this->decorateHistory($rows); }
    public function historyPage(int $id,int $page=1,int $perPage=20,array $filters=[]): array { $lead=$this->findLead($id);if(!$lead)throw new RuntimeException('Lead not found.');$query=$this->historyRows($id,(int)$lead['clinic_id'],$filters);$rows=$query->paginate($perPage,'crm_history');return ['lead'=>$lead,'history'=>$this->decorateHistory($rows),'pager'=>$this->history->pager,'filters'=>$filters,'total'=>$this->history->pager->getTotal('crm_history')]; }
    public function historyEventTypes(int $id): array { $lead=$this->findLead($id);if(!$lead)throw new RuntimeException('Lead not found.');$rows=$this->historyRows($id,(int)$lead['clinic_id'])->select('event_type')->groupBy('event_type')->findAll();return array_values(array_filter(array_map(static fn(array $row): string => (string)($row['event_type']??''),$rows))); }
    public function historySummary(int $id): array { $lead=$this->findLead($id);if(!$lead)throw new RuntimeException('Lead not found.');$base=$this->db->table('crm_lead_history')->where(['lead_id'=>$id,'clinic_id'=>(int)$lead['clinic_id']]);$total=(clone $base)->countAllResults();$remarks=(clone $base)->where('remarks !=','')->where('remarks IS NOT NULL',null,false)->countAllResults();$last=(clone $base)->select('created_at')->orderBy('id','DESC')->get()->getRowArray();$followUps=$this->db->table('crm_lead_followups')->where(['lead_id'=>$id,'clinic_id'=>(int)$lead['clinic_id']])->countAllResults();$assigned=$this->db->table('users')->select('username')->where('id',(int)($lead['assigned_user_id']??0))->get()->getRowArray();return ['total_events'=>$total,'remarks_count'=>$remarks,'follow_ups'=>$followUps,'last_activity'=>$last['created_at']??null,'assigned_user'=>$assigned['username']??null,'conversion_status'=>!empty($lead['converted_appointment_id'])?'Appointment booked':(!empty($lead['converted_patient_id'])?'Patient converted':'Not converted')]; }
    public function convertToPatient(int $id,int $actor): array { $lead=$this->findLead($id);if(!$lead)throw new RuntimeException('Lead not found.');if(!empty($lead['converted_patient_id']))return ['id'=>(int)$lead['converted_patient_id']];if(empty($lead['date_of_birth']))throw new RuntimeException(json_encode(['date_of_birth'=>'Date of birth is required before converting this lead to a patient.']));if(empty($lead['telephone_country_code_id']))throw new RuntimeException(json_encode(['telephone_country_code_id'=>'Select a telephone country code before converting this lead.']));$parts=preg_split('/\s+/',trim($lead['full_name']),2);$result=(new PatientRegistrationService())->register(['clinic_id'=>(int)$lead['clinic_id'],'first_name'=>$parts[0]??$lead['full_name'],'last_name'=>$parts[1]??'','gender'=>$lead['gender'],'date_of_birth'=>$lead['date_of_birth'],'email'=>$lead['email']??'','mobile_number'=>$lead['mobile_number'],'telephone_country_code_id'=>(int)$lead['telephone_country_code_id'],'country_code'=>$lead['country_code']??$lead['lead_country_code']],$actor,['source_type'=>'self','source_user_id'=>$actor,'source_reference'=>$lead['lead_number']]);$status=$this->statuses->where('code','converted')->first();$this->leads->update($id,['converted_patient_id'=>$result['id'],'converted_at'=>date('Y-m-d H:i:s'),'converted_by'=>$actor,'lead_status_id'=>$status['id'],'updated_by'=>$actor]);$this->record($id,'converted_to_patient',null,['patient_id'=>$result['id']],$actor);return $result; }
    public function convertToAppointment(int $id,array $input,int $actor): array { $lead=$this->findLead($id);if(!$lead)throw new RuntimeException('Lead not found.');if(!empty($lead['converted_appointment_id']))return ['id'=>(int)$lead['converted_appointment_id']];$doctor=(int)($input['doctor_id']??$lead['preferred_doctor_id']??0);$date=$this->date($input['appointment_date']??$lead['next_follow_up_date']??'');$time=trim((string)($input['appointment_time']??$lead['next_follow_up_time']??''));$service=trim((string)($input['service_name']??$lead['interested_service']??''));if($doctor<1||!$date||!preg_match('/^\d{2}:\d{2}(:\d{2})?$/',$time)||$service==='')throw new RuntimeException(json_encode(['appointment'=>'Doctor, date, time and service are required.']));if($date<date('Y-m-d'))throw new RuntimeException(json_encode(['appointment_date'=>'Appointment date cannot be in the past.']));$patientId=(int)($lead['converted_patient_id']??0);if($patientId<1){$patient=$this->convertToPatient($id,$actor);$patientId=(int)$patient['id'];}$doctorRow=$this->db->table('doctors')->where(['id'=>$doctor,'clinic_id'=>$lead['clinic_id'],'status'=>1])->get()->getRowArray();if(!$doctorRow)throw new RuntimeException(json_encode(['doctor_id'=>'The selected doctor is invalid for this clinic.']));$apptTime=strlen($time)===5?$time.':00':$time;$conflict=$this->db->table('appointments')->where(['doctor_id'=>$doctor,'clinic_id'=>$lead['clinic_id'],'appointment_date'=>$date,'appointment_time'=>$apptTime])->whereIn('status',['scheduled','confirmed','checked_in','in_queue'])->get()->getRowArray();if($conflict)throw new RuntimeException(json_encode(['appointment_time'=>'The selected appointment time is already booked.']));$now=date('Y-m-d H:i:s');$this->db->table('appointments')->insert(['appointment_number'=>'TMP-'.bin2hex(random_bytes(6)),'patient_id'=>$patientId,'doctor_id'=>$doctor,'clinic_id'=>$lead['clinic_id'],'appointment_date'=>$date,'appointment_time'=>$apptTime,'duration_minutes'=>15,'appointment_type'=>'in_person','service_name'=>$service,'status'=>'scheduled','created_by_type'=>'user','created_by_id'=>$actor,'booking_source'=>'crm','created_at'=>$now,'updated_at'=>$now]);$appointmentId=(int)$this->db->insertID();$this->db->table('appointments')->where('id',$appointmentId)->update(['appointment_number'=>'APT-'.str_pad((string)$appointmentId,6,'0',STR_PAD_LEFT)]);$status=$this->statuses->where('code','appointment_booked')->first();$this->leads->update($id,['converted_patient_id'=>$patientId,'converted_appointment_id'=>$appointmentId,'converted_at'=>date('Y-m-d H:i:s'),'converted_by'=>$actor,'lead_status_id'=>$status['id'],'updated_by'=>$actor]);$this->record($id,'converted_to_appointment',null,['appointment_id'=>$appointmentId,'patient_id'=>$patientId],$actor);return ['id'=>$appointmentId,'patient_id'=>$patientId]; }
    private function historyRows(int $leadId,int $clinicId,array $filters=[]) { $query=$this->history->select('crm_lead_history.*, users.username AS actor_name')->join('users','users.id = crm_lead_history.actor_user_id','left')->where('crm_lead_history.lead_id',$leadId)->where('crm_lead_history.clinic_id',$clinicId);if(($filters['event_type']??'')!=='')$query->where('crm_lead_history.event_type',$filters['event_type']);if(($filters['actor']??'')!=='')$query->groupStart()->like('users.username',$filters['actor'])->orWhere('crm_lead_history.actor_user_id',(int)$filters['actor'])->groupEnd();if(($filters['from']??'')!=='')$query->where('crm_lead_history.created_at >=',$filters['from'].' 00:00:00');if(($filters['to']??'')!=='')$query->where('crm_lead_history.created_at <=',$filters['to'].' 23:59:59');return $query->orderBy('crm_lead_history.id','DESC'); }
    private function decorateHistory(array $rows): array { $timezone=new \DateTimeZone((string)config('App')->appTimezone); foreach($rows as &$row){$row['created_at_display']=$this->formatHistoryDateTime($row['created_at']??null,$timezone);$event=(string)($row['event_type']??'');$row['source_module']=str_starts_with($event,'follow_up_')?'CRM / Follow-up':(str_starts_with($event,'converted_')?'CRM / Conversion':'CRM / Lead');} unset($row); return $rows; }
    private function formatHistoryDateTime(?string $value,\DateTimeZone $timezone): string { if(!$value)return '—'; try{return (new \DateTimeImmutable($value,$timezone))->setTimezone($timezone)->format('d-m-Y h:i A');}catch(\Throwable $e){return '—';} }
    private function decorateRows(array $rows): array { $formatter=new TelephoneContactService($this->telephoneCodes); foreach($rows as &$row){if(!array_key_exists('interested_service',$row)&&!empty($row['lead_id'])){$leadService=$this->db->table('crm_leads')->select('interested_service')->where('id',(int)$row['lead_id'])->get()->getRowArray();$row['interested_service']=$leadService['interested_service']??null;}$row['mobile_display']=$formatter->formatDisplay($row['lead_country_code']??$row['country_code']??null,$row['mobile_number']??null,$row['country_code']??null);$serviceValue=trim((string)($row['interested_service']??''));$row['service_name']=null;if($serviceValue!==''&&ctype_digit($serviceValue)){$service=$this->services->forScope($this->clinicId()>0?$this->clinicId():null)->where('id',(int)$serviceValue)->first();$row['service_name']=$service['name']??null;}if($row['service_name']===null&&$serviceValue!==''&&!ctype_digit($serviceValue))$row['service_name']=$serviceValue;} unset($row); return $rows; }
    private function record(int $leadId,string $event,?array $previous,?array $new,int $actor,?int $followUpId=null): void { $lead=$this->findLead($leadId);$this->history->insert(['lead_id'=>$leadId,'clinic_id'=>(int)($lead['clinic_id']??$this->clinicId()),'event_type'=>$event,'previous_value'=>$previous?json_encode($previous):null,'new_value'=>$new?json_encode($new):null,'remarks'=>$new['remarks']??null,'follow_up_id'=>$followUpId,'actor_user_id'=>$actor,'created_at'=>date('Y-m-d H:i:s')]);service('audit')->record('crm.'.$event,['lead_id'=>$leadId,'clinic_id'=>$lead['clinic_id']??$this->clinicId(),'follow_up_id'=>$followUpId]); }
    private function date(string $value): ?string { $value=trim($value);if($value==='')return null;if(function_exists('rootins_parse_date')){$parsed=rootins_parse_date($value);if($parsed)return $parsed;}foreach(['Y-m-d','d-m-Y','d/m/Y'] as $format){$date=\DateTime::createFromFormat($format,$value);if($date&&$date->format($format)===$value)return $date->format('Y-m-d');}return null; }
}
